insert into public.questions (id, chapter_id, sort_order, question_type, prompt, description, config) values
  ('00000000-0000-4000-8002-000001000001', '00000000-0000-4000-8001-000000000001', 1, 'list', 'あなたの周りの売れているセールスパーソンを3人イメージし、その人の特徴をそれぞれ、挙げて下さい。', '', '{"count": 3}'::jsonb),
  ('00000000-0000-4000-8002-000001000002', '00000000-0000-4000-8001-000000000001', 2, 'list', 'あなたの周りの売れていないセールスパーソンを3人イメージし、その人の特徴をそれぞれ、挙げて下さい。', '', '{"count": 3}'::jsonb),
  ('00000000-0000-4000-8002-000001000003', '00000000-0000-4000-8001-000000000001', 3, 'two_category', 'あなたがトップセールスパーソンになるために必要なもので、自分がすでに兼ね備えているものと、まだ足りないものは何か挙げてみましょう。', '', '{"columns": [{"key": "have", "label": "満たされているもの"}, {"key": "lack", "label": "足りないもの"}], "sections": [{"key": "mind", "label": "① 心構え、考え方（マインド）の点で現在、満たされているもの、足りないもの。", "hint": "例：4つの自信、積極的な心構え"}, {"key": "knowledge", "label": "② 知識（ナレッジ）の点で、現在満たされているもの、足りないもの。", "hint": "例：商品知識、競合他社の情報、業界の専門知識"}, {"key": "skill", "label": "③ 技術（スキル）の点で、現在満たされているもの、足りないもの。", "hint": "例：クロージング、タイムマネジメント、新規顧客開拓"}]}'::jsonb),
  ('00000000-0000-4000-8002-000001000004', '00000000-0000-4000-8001-000000000001', 4, 'free_text', 'このプログラムを活用することで身につけたいもの、得たいもの、手にしたいものは何ですか。', '', '{}'::jsonb),
  ('00000000-0000-4000-8002-000001000005', '00000000-0000-4000-8001-000000000001', 5, 'commitment', 'この章で学んだことの中から、実行しようと思うことを具体的に一つ挙げて下さい。', '', '{}'::jsonb)
