insert into public.questions (id, chapter_id, sort_order, question_type, prompt, description, config) values
  ('00000000-0000-4000-8002-000004000001', '00000000-0000-4000-8001-000000000004', 1, 'free_text', '自分自身の自信を高めるために、あなたが実行できることはどのようなことですか。', '', '{}'::jsonb),
  ('00000000-0000-4000-8002-000004000002', '00000000-0000-4000-8001-000000000004', 2, 'free_text', '職業に対しての自信を高めるために、あなたが実行できることはどのようなことですか。', '', '{}'::jsonb),
  ('00000000-0000-4000-8002-000004000003', '00000000-0000-4000-8001-000000000004', 3, 'multi_field', 'あなたがモデルとしたい人物はいますか。もしいるとしたら、人物名を書き、その人がなぜ魅力的なのかを書き出して下さい。', '', '{"fields": [{"key": "name", "label": "モデルとしたい人物名", "single_line": true}, {"key": "reason", "label": "その人物が魅力的な理由"}]}'::jsonb),
  ('00000000-0000-4000-8002-000004000004', '00000000-0000-4000-8001-000000000004', 4, 'free_text', 'トップセールスパーソンになるためには、どのような人々と付き合っていく必要性があるでしょうか。具体的に考えられる人物名を挙げて下さい。', '', '{}'::jsonb),
  ('00000000-0000-4000-8002-000004000005', '00000000-0000-4000-8001-000000000004', 5, 'list', 'あなたの長所を5つ以上書き出して下さい。', '', '{"count": 5, "allow_add": true}'::jsonb),
  ('00000000-0000-4000-8002-000004000006', '00000000-0000-4000-8001-000000000004', 6, 'multi_field', 'あなたの過去の失敗体験を書き出して下さい。その体験をキャリアに置き換えるとどのような学びの種があったと捉えることができますか。', '※失敗体験がない場合は、現在ある逆境にどのような学びの種があるかを書き出して下さい。', '{"fields": [{"key": "experience", "label": "過去の失敗体験・現在の逆境"}, {"key": "learning", "label": "そこから得られた学び"}]}'::jsonb),
  ('00000000-0000-4000-8002-000004000007', '00000000-0000-4000-8001-000000000004', 7, 'commitment', 'この章で学んだことの中から、実行しようと思うことを具体的に一つ挙げて下さい。', '', '{}'::jsonb)
